use std::collections::HashMap;

fn get_config_value(config: &HashMap<&str, &str>, key: &str) -> &str {
    config.get(key).unwrap()
}

fn main() {
    let mut config = HashMap::new();
    config.insert("host", "localhost");
    config.insert("timeout", "30");
    let port = get_config_value(&config, "port");
    println!("port: {}", port);
}
